// Welcome preferences and sample selection contain no decision inputs.
let welcomeSeen=false,welcomeSelection=null,currentExampleId=null,exampleFilter='all';
const welcomeSkipKey='decider-skip-welcome-v1',welcomeDrawKey='decider-welcome-last-draw-v1';
function skipWelcome(){try{return localStorage.getItem(welcomeSkipKey)==='yes';}catch{return false;}}
function rememberWelcomeSkip(value){try{if(value)localStorage.setItem(welcomeSkipKey,'yes');else localStorage.removeItem(welcomeSkipKey);}catch{}}
function drawWelcomeExamples(){
 let previous=[];try{const saved=JSON.parse(localStorage.getItem(welcomeDrawKey)||'[]');if(Array.isArray(saved))previous=saved.filter(id=>typeof id==='string');}catch{}
 welcomeSelection=DeciderExamples.choose(previous,Math.random,exampleFilter);
 try{localStorage.setItem(welcomeDrawKey,JSON.stringify(welcomeSelection.map(e=>e.id)));}catch{}
 return welcomeSelection;
}
const exampleCategories=[['all','A random mix'],['public','Big public decisions'],['business','Business'],['money','Money'],['happiness','Happiness']];
function exampleCategory(e){return e.category==='public'?'Big public decisions':e.category==='business'?'Business · Money':e.kind==='money'?'Money':'Happiness';}
function exampleFilterControl(){return `<label class="example-filter" for="example-filter">Pick a topic<select id="example-filter">${exampleCategories.map(([id,label])=>`<option value="${id}" ${id===exampleFilter?'selected':''}>${label}</option>`).join('')}</select></label>`;}
function exampleCard(e){const answer=SIGFI.quick(DeciderExamples.stateFor(e)).goForIt;return `<a class="example-card ${e.kind} ${e.category==='public'?'public':''}" href="#example/${e.id}"><span class="example-category">${exampleCategory(e)}</span><strong>${escapeText(e.question)}</strong><span class="card-answer ${answer?'is-yes':'is-no'}">The Decider’s AI-free decision is <b>${answer?'Yes':'No'}</b></span><span class="example-read">Explore why <span aria-hidden="true">↗</span></span></a>`;}
function wireExampleFilter(library=false){document.getElementById('example-filter').onchange=e=>{exampleFilter=e.target.value;welcomeSelection=null;if(library)renderExampleLibrary();else{drawWelcomeExamples();renderWelcome();}document.getElementById('example-filter').focus({preventScroll:true});};}
function enterOwnDecision(){welcomeSeen=true;history.replaceState(null,'',location.pathname+location.search);screen=0;returnScreen=0;render();scrollTop();}
function renderWelcome(){
 const examples=welcomeSelection||drawWelcomeExamples();document.body.classList.remove('results');
 app.innerHTML=`<section class="welcome-hero"><p class="welcome-eyebrow own-eyebrow">Your decision</p><h1 class="brand-title welcome-brand"><span class="brand-the">The</span>Decider<span>.</span></h1><p class="brand-strapline welcome-promise">There is a best choice.<br>Let’s find it.</p><p class="welcome-intro">A decision of your own? Start here.</p><button class="primary welcome-start" id="welcome-start">Make my decision <span aria-hidden="true">→</span></button><label class="welcome-skip"><input type="checkbox" id="welcome-skip" ${skipWelcome()?'checked':''}><span>Skip this next time</span></label></section><section class="welcome-examples" aria-labelledby="example-heading"><p class="welcome-eyebrow">The example collection · Read &amp; explore</p><h2 id="example-heading">What would The Decider say?</h2><p class="welcome-description">Big debates. Everyday dilemmas. See where The Decider lands.</p><div class="example-grid">${examples.map(exampleCard).join('')}</div><div class="example-browse"><button type="button" class="plain" id="welcome-more">${exampleFilter!=='all'&&DeciderExamples.items.filter(e=>e.category===exampleFilter).length<=4?'Shuffle these examples':'Show me four more'}</button><a href="#examples">Browse all ${DeciderExamples.items.length} examples →</a></div>${exampleFilterControl()}<p class="example-results-note">Agree? Disagree? Get into the numbers and see what flips the answer.</p></section><p class="quiet welcome-reassurance">Your answers. Explainable reasoning. No AI making the choice for you.</p>`;
 document.getElementById('welcome-start').onclick=enterOwnDecision;document.getElementById('welcome-skip').onchange=e=>rememberWelcomeSkip(e.target.checked);wireExampleFilter();
 document.getElementById('welcome-more').onclick=()=>{drawWelcomeExamples();renderWelcome();document.getElementById('example-heading').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.getElementById('welcome-more').focus({preventScroll:true});};
}
function renderExampleLibrary(){
 const groups=[['public','Big public decisions'],['business','For your business'],['money','For your money'],['happiness','For your life']].filter(([category])=>exampleFilter==='all'||category===exampleFilter);
 app.innerHTML=`<a class="back example-back" href="#welcome">← Back to welcome</a><p class="welcome-eyebrow collection-eyebrow">The example collection · Read &amp; explore</p><h1 class="input-title">Big questions.<br>Clear reasoning.</h1><p>Read an example. See why the answer changes.</p><button class="explore-button collection-own" id="library-start">Start my own decision →</button>${groups.map(([category,title])=>`<section class="example-library-group"><h2>${title}</h2><div class="example-grid">${DeciderExamples.items.filter(e=>e.category===category).map(exampleCard).join('')}</div></section>`).join('')}${exampleFilterControl()}`;
 document.getElementById('library-start').onclick=enterOwnDecision;wireExampleFilter(true);
}
function exampleMoney(n,e){return new Intl.NumberFormat('en-GB',{style:'currency',currency:e.currency,maximumFractionDigits:0}).format(n);}
function exampleFeeling(n,e){
 if(n===0)return 'Indifferent';
 const words=emotionalWords[e.importance],index=Math.min(4,Math.max(0,Math.ceil(Math.abs(n)/5)-1));
 return words[n>0?'positive':'negative'][index];
}
function renderExample(){
 const e=DeciderExamples.items.find(e=>e.id===currentExampleId);
 if(!e){app.innerHTML='<h1 class="input-title">Let’s find another example.</h1><p>That example isn’t in this collection.</p><a class="explore-button" href="#examples">Browse the examples</a>';return;}
 const r=SIGFI.quick(DeciderExamples.stateFor(e)),changed=SIGFI.quick(DeciderExamples.stateFor(e,true)),cash=e.kind==='money',labels=e.scenarioLabels||['As hoped','Things go wrong'];
 const amount=n=>cash?exampleMoney(n,e):exampleFeeling(n,e);
 const inputs=[['A','Go for it',labels[0]],['B','Go for it',labels[1]],['C','Don’t go for it',labels[0]],['D','Don’t go for it',labels[1]]];
 const outcomeRows=inputs.map(([key,choice,situation])=>`<div class="example-outcome"><div><span class="example-situation">${choice} · ${escapeText(situation)}</span><strong>${escapeText(amount(e.pay[key]))}</strong></div><p>${escapeText(e.notes[key])}</p></div>`).join('');
 const chance=new Intl.NumberFormat('en-GB',{maximumFractionDigits:6}).format(e.p)+'%';
 const sources=e.sources?.length?`<ul class="example-sources">${e.sources.map(s=>`<li><a href="${escapeText(s.url)}" target="_blank" rel="noopener noreferrer">${escapeText(s.label)}</a></li>`).join('')}</ul>`:'';
 app.innerHTML=`<a class="back example-back" href="#welcome">← Back to examples</a><article class="worked-example compact-example"><p class="reading-mode">The example collection · Read &amp; explore</p><p class="example-category story-category ${e.kind}">${exampleCategory(e)}</p><h1 class="example-title">${escapeText(e.question)}</h1>${e.category==='public'?`<p class="example-perspective">${escapeText(e.perspective)}</p>`:''}<section class="example-verdict ${r.goForIt?'example-yes':'example-no'}"><span>The Decider’s AI-free decision is</span><h2>${r.goForIt?'Yes.':'No.'}</h2></section><h2>The Decider’s take</h2><p>${escapeText(e.shortWhy)}</p><section class="example-change"><h2>What would change it?</h2><p>${escapeText(e.shortChange)}</p><p class="example-change-answer">The Decider’s new decision: <strong>${changed.goForIt?'Yes.':'No.'}</strong></p></section><button class="example-try" id="example-own">Try changing this example →</button><p class="example-own-note">Opens the calculator with the example’s answers.</p><details class="example-details optional"><summary>Peek at the numbers &amp; assumptions</summary><p>${escapeText(e.story)}</p><div class="example-horizon"><span>Period</span><strong>${escapeText(e.period)}</strong></div><div class="example-scenarios"><p><span>${escapeText(labels[0])}</span>${escapeText(e.situations[0])}</p><p><span>${escapeText(labels[1])}</span>${escapeText(e.situations[1])}</p></div><p class="example-model-note">${cash?'Net gains or losses after the costs described, compared over the same period.':'Feelings are personal. These are the example’s answers.'}</p>${outcomeRows}<div class="example-context"><div><span>Chance of ${escapeText(e.scenarioLabels?labels[0].toLowerCase():'things turning out as hoped')}</span><strong>${chance}</strong></div><div><span>${cash?'Starting financial resources':'Emotional strength'}</span><strong>${cash?exampleMoney(e.resources,e):robustness(e.resources)}</strong></div></div>${cash?'':`<p class="example-model-note">${escapeText(e.importance)}. Emotional strength: ${e.resources} on the prototype scale. Outcome values: ${Object.values(e.pay).join(', ')}. These values are provisional, not a clinical measure.</p>`}<p class="example-model-note">${escapeText(e.basis||'These are the example’s inputs. Change them and see where The Decider lands.')}</p>${sources}<button class="explore-button" id="example-blank">Start this question from scratch</button></details>${e.category==='public'||e.category==='business'?`<a href="#contact" class="consultant-box example-consultant" id="example-consultant"><h2>A bigger decision to work through?</h2><p>Put The Decider to work on the choice that matters to you.</p><span>Explore it with a consultant →</span></a>`:''}<a class="plain example-all" href="#examples">Browse more examples →</a></article><div class="personal-exit"><p>Have a decision of your own?</p><button class="primary" id="example-personal">Start my own decision →</button></div>`;
 document.getElementById('example-personal').onclick=enterOwnDecision;document.getElementById('example-own').onclick=()=>startWorkedExample(e,true);document.getElementById('example-blank').onclick=()=>startWorkedExample(e,false);
 const consultant=document.getElementById('example-consultant');if(consultant)consultant.onclick=()=>{window.DeciderExampleContact={id:e.id};};
}
function startWorkedExample(e,withAnswers){
 window.DeciderExampleContact=null;welcomeSeen=true;history.replaceState(null,'',location.pathname+location.search);returnScreen=0;start(e.kind);
 state.title=e.question;state.importance=e.importance;if(e.scenarioLabels)state.exampleScenarios=e.scenarioLabels;
 if(withAnswers){const d=DeciderExamples.stateFor(e);Object.assign(state,d,{exampleId:e.id,simplePay:d.pay.C,normalPay:{C:d.pay.C,D:d.pay.D}});state.upside=niceScale(Math.max(0,...Object.values(state.pay)));state.downside=niceScale(Math.max(0,...Object.values(state.pay).map(n=>-n)));}
 else state.exampleQuestion=e.id;
 render();scrollTop();
}
